package com.salespunch360.mobile.ui.account.purchase
import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.LazyColumn;import androidx.compose.foundation.lazy.itemsIndexed;import androidx.compose.material3.*;import androidx.compose.runtime.Composable;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import com.salespunch360.mobile.AccountPurchaseViewModel;import com.salespunch360.mobile.account.*;import com.salespunch360.mobile.ui.account.sales.SelectField
@Composable fun PurchaseEditor(d:PurchaseDraft,s:PurchaseState,vm:AccountPurchaseViewModel){val sources=s.sources.filter{it.str("type")=="PURCHASE_BILL"&&it.str("branchId")==d.branchId&&it.str("vendorId")==d.vendorId},sourceLines=sources.firstOrNull{it.str("id")==d.sourceDocumentId}?.array("lines").orEmpty();AlertDialog(onDismissRequest=vm::closeDraft,title={Text("New ${d.type.replace('_',' ')}")},confirmButton={Button(enabled=!s.saving&&d.vendorId.isNotBlank()&&d.lines.isNotEmpty(),onClick=vm::save){Text("Create draft")}},dismissButton={TextButton(vm::closeDraft){Text("Cancel")}},text={LazyColumn(verticalArrangement=Arrangement.spacedBy(8.dp)){item{SelectField("Type",d.type,s.types.map{it to it.replace('_',' ')}){vm.edit(d.copy(type=it))}};item{SelectField("Branch",d.branchId,s.branches.map{it.id to it.name}){vm.edit(d.copy(branchId=it,vendorId=""))}};item{SelectField("Vendor",d.vendorId,s.vendors.map{it.id to it.name}){vm.edit(d.copy(vendorId=it))}};if(d.type=="DEBIT_NOTE")item{SelectField("Source purchase bill",d.sourceDocumentId,sources.map{it.str("id") to it.str("documentNumber")}){vm.edit(d.copy(sourceDocumentId=it))}};if(d.type=="PURCHASE_BILL")item{SelectField("Source purchase order",d.sourcePurchaseOrderId,s.purchaseOrders.filter{it.str("branchId")==d.branchId&&it.str("vendorId")==d.vendorId}.map{it.str("id") to it.str("documentNumber")}){vm.edit(d.copy(sourcePurchaseOrderId=it))}};item{OutlinedTextField(d.issueDate,{vm.edit(d.copy(issueDate=it))},label={Text("Issue date")})};item{OutlinedTextField(d.dueDate,{vm.edit(d.copy(dueDate=it))},label={Text("Due date")})};item{SelectField("Purpose",d.purpose,listOf("OFFICE" to "Office","PROJECT" to "Project")){vm.edit(d.copy(purpose=it))}};if(d.purpose=="PROJECT")item{SelectField("Project",d.projectId,s.projects.map{it.id to it.name}){vm.edit(d.copy(projectId=it))}};item{SelectField("Classification",d.classification,listOf("PURCHASE_COST" to "Purchase cost","GENERAL_EXPENSES" to "General expenses","FIXED_ASSET" to "Fixed asset")){vm.edit(d.copy(classification=it))}};item{SelectField("Tax mode",d.taxMode,listOf("EXCLUSIVE" to "Exclusive","INCLUSIVE" to "Inclusive")){vm.edit(d.copy(taxMode=it))}};itemsIndexed(d.lines){i,l->PurchaseLine(i,l,d,s,sourceLines,vm)};item{OutlinedButton(vm::addLine){Text("Add line")}};item{OutlinedTextField(d.notes,{vm.edit(d.copy(notes=it))},label={Text("Notes")})};item{Text("Totals, GST, stock valuation, and postings are authoritative only after the server response.",style=MaterialTheme.typography.bodySmall)}}})}
@Composable private fun PurchaseLine(i:Int,l:SalesLineDraft,d:PurchaseDraft,s:PurchaseState,sourceLines:List<kotlinx.serialization.json.JsonObject>,vm:AccountPurchaseViewModel){val masters=when(l.lineType){"MATERIAL"->s.products;"SERVICE"->s.services;"SUBCONTRACT"->s.workPackages;else->emptyList()};ElevatedCard{Column(Modifier.padding(10.dp)){if(d.type=="DEBIT_NOTE")SelectField("Original line",l.sourceCommercialLineId,sourceLines.map{it.str("id") to "${it.str("itemName")} · ${it.str("quantity")}"}){id->val x=sourceLines.first{it.str("id")==id};vm.line(i,l.copy(sourceCommercialLineId=id,lineType=x.str("lineType"),sourceId=x.str("productId").ifBlank{x.str("serviceId").ifBlank{x.str("workPackageId")}},itemName=x.str("itemName"),quantity=x.str("quantity"),rate=x.str("rate"),taxRate=x.str("taxRate"))};SelectField("Line type",l.lineType,listOf("MATERIAL" to "Material","SERVICE" to "Service","SUBCONTRACT" to "Subcontract","CUSTOM" to "Custom")){vm.line(i,l.copy(lineType=it,sourceId=""))};if(l.lineType=="CUSTOM")OutlinedTextField(l.itemName,{vm.line(i,l.copy(itemName=it))},label={Text("Name")})else SelectField("Item",l.sourceId,masters.map{it.id to it.name}){id->val m=masters.first{it.id==id};vm.line(i,l.copy(sourceId=id,rate=m.rate.orEmpty(),taxRate=m.taxRate.orEmpty()))};Row{OutlinedTextField(l.quantity,{vm.line(i,l.copy(quantity=it))},label={Text("Qty")},modifier=Modifier.weight(1f));OutlinedTextField(l.rate,{vm.line(i,l.copy(rate=it))},label={Text("Rate")},modifier=Modifier.weight(1f))};OutlinedTextField(l.taxRate,{vm.line(i,l.copy(taxRate=it))},label={Text("GST %")});if(l.sourceId.isNotBlank()&&masters.firstOrNull{it.id==l.sourceId}?.trackInventory==true)SelectField("Warehouse",l.warehouseId,s.warehouses.filter{it.branchId==d.branchId}.map{it.id to it.name}){vm.line(i,l.copy(warehouseId=it))};if(d.type=="DEBIT_NOTE")OutlinedTextField(l.stockReturnQuantity,{vm.line(i,l.copy(stockReturnQuantity=it))},label={Text("Physical return quantity")});if(d.lines.size>1)TextButton({vm.remove(i)}){Text("Remove")}}}}
